"""Write the teacher-forced ClassEval page directly from the complete audit."""
import json
from pathlib import Path
here=Path(__file__).resolve().parent
root=here.parent/"class_memory"
result=json.loads((root/"results.json").read_text("utf8"))
main=result["main"]
g=main["scores"]
contrast=main["graph_minus"]["bm25_line"]["pass_all"]
fmt=lambda x:f"{100*x:.2f}".replace(".",",").replace("-","−")
group=lambda n:f"{n:,}".replace(","," ")
labels={"none":"Пустая память","bm25_method":"BM25 по методам","bm25_line":"BM25 по строкам","graph":"Граф полей и зависимостей","placebo":"Переставленные веса","full":"Доступный текст до 800 токенов"}
assert set(labels)==set(g)
order=['none','bm25_method','bm25_line','graph','placebo','full']
data=[]
for a in order:
    m=g[a]
    data.append(f"| {labels[a]} | {m['pass_all']} | {m['passed']} | {group(m['memory_tokens'])} |")
text=f"""# Помог ли граф написать работающий метод
> В {main['n']} заданиях из {main['classes']} классов локальный Qwen3.8-27B получил контракт, сигнатуры, конструктор и выбранные политикой строки прежних методов. Граф дал {g['graph']['pass_all']} методов с полностью прошедшими тестами, поиск BM25 по тем же строкам — {g['bm25_line']['pass_all']}.
Здесь предшествующие методы взяты из опубликованного эталона. Модель пишет следующий метод с одного запроса. Для проверки результата его вставляют в полный эталонный класс и запускают профильный авторский набор. Цели, будущие тела и скрытая оценка недоступны решателю. В открытых контрактах 54 методов есть вызовы с теми же буквальными аргументами, что в тестах. Все способы видят один и тот же контракт.
@ 6 3.0 3.0 3.0
| Память в запросе | Методы, из 108 | Тесты, из 551 | Сумма токенов памяти |
{chr(10).join(data)}
Граф связывает присваивания полям объекта со строками, от которых зависят значения и управляющие условия. Доступно до 160 токенов памяти на метод. Контроль полного текста может получить до 800. В сравнении со строковым BM25 получено {contrast['wins']} выигрышей и {contrast['losses']} потерь. Разность полного успеха {fmt(contrast['delta'])} п.п., кластерный 95% ДИ [{fmt(contrast['ci'][0])}; {fmt(contrast['ci'][1])}].
Граф и BM25 показали 76 из 81 доступного нужного поля объекта. На 76 методах запросы полностью совпали, на 32 различались. Шесть назначений для каждого из 108 методов дали {result['unique_calls']} разных запросов после объединения совпадающих входов. Qwen3.8-27B-UD-Q4_K_M исполнялся в llama.cpp на локальной RTX 3090, температура 0, один ответ до 384 новых токенов, режим размышления отключён. При независимом повторе с 17 дополнительными чистыми операциями Python все показатели полных успехов сохранились. У пустого контроля отдельные проверки дали 417 вместо 418. Причина переменного результата установлена у метода, который возвращает list(set(...)): тест требует определённый порядок, а хеширование строк зависит от процесса.
~ [ClassEval, постановка авторов](https://arxiv.org/abs/2308.01861) · [Исходные задачи и тесты](https://github.com/FudanSELab/ClassEval/tree/eaeac44d0d5dcd8a95feec50726d66fedc73a98f)"""
(here/"pages/08.md").write_text(text,encoding="utf8")
